/**
 * 商户 mp-weixin：用微信开发者工具 automator 核对首页「扫码」按钮样式。
 */
import fs from 'node:fs';
import path from 'node:path';
import automator from 'miniprogram-automator';

const ROOT = path.resolve('C:/Users/cwx/OneDrive/Desktop/demo/ai-cabinet');
const PROJECT = path.join(ROOT, 'clients/merchant-mp/dist/dev/mp-weixin');
const CLI = 'D:/devTools/微信web开发者工具/cli.bat';
const OUT = path.join(ROOT, '.tmp/mp-scan-btn');
const PHONE = '13800138001';
const PASSWORD = '123456';

function log(...args) {
  console.log(new Date().toISOString(), ...args);
}

async function shot(mp, name) {
  const dest = path.join(OUT, `${name}.png`);
  await mp.screenshot({ path: dest });
  const st = fs.statSync(dest);
  log('shot', name, `${st.size}B`);
  if (st.size < 20_000) {
    log('WARN small screenshot, may be blank', dest);
  }
  return dest;
}

async function tapByText(page, re) {
  const nodes = await page.$$('button, .app-btn, text, view');
  for (const n of nodes) {
    let t = '';
    try {
      t = (await n.text()) || '';
    } catch {
      continue;
    }
    if (re.test(t.trim())) {
      await n.tap();
      return t.trim();
    }
  }
  return null;
}

async function main() {
  fs.mkdirSync(OUT, { recursive: true });
  log('launch', PROJECT);
  const mp = await automator.launch({
    cliPath: CLI,
    projectPath: PROJECT,
    trustProject: true,
    timeout: 180000
  });
  log('connected');
  await mp.pageWaitTimeout?.catch?.(() => {});
  await new Promise((r) => setTimeout(r, 4000));

  let page = await mp.currentPage();
  log('page', page?.path);
  await shot(mp, '01-first');

  if (page?.path?.includes('login')) {
    const inputs = (await page.$$('input')) || [];
    log('inputs', inputs.length);
    if (inputs[0]?.input) await inputs[0].input(PHONE);
    if (inputs[1]?.input) await inputs[1].input(PASSWORD);
    const tapped = await tapByText(page, /^登录$|^登录中/);
    log('tapped login', tapped);
    await new Promise((r) => setTimeout(r, 4500));
    page = await mp.currentPage();
    log('after login', page?.path);
    await shot(mp, '02-after-login');
  }

  if (!page?.path?.includes('home')) {
    try {
      page = await mp.switchTab('/pages/home/home');
    } catch (e) {
      log('switchTab fail, reLaunch', e.message);
      page = await mp.reLaunch('/pages/home/home');
    }
    await new Promise((r) => setTimeout(r, 4000));
    page = await mp.currentPage();
    log('home', page?.path);
    await shot(mp, '03-home');
  }

  page = await mp.currentPage();
  const scanBtn = page ? await page.$('.scan-btn') : null;
  const scanCard = page ? await page.$('.scan-card') : null;
  const info = {};
  if (scanBtn) {
    info.btnText = await scanBtn.text();
    info.btnSize = await scanBtn.size();
    info.bg = await scanBtn.style('backgroundColor');
    info.color = await scanBtn.style('color');
    info.radius = await scanBtn.style('borderRadius');
    info.height = await scanBtn.style('height');
  }
  if (scanCard) {
    info.cardText = await scanCard.text();
  }
  fs.writeFileSync(path.join(OUT, 'styles.json'), JSON.stringify(info, null, 2));
  log('styles', JSON.stringify(info));
  await shot(mp, '04-home-scan');
  log('done, leaving DevTools open');
  mp.disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

