import fs from 'node:fs';
import path from 'node:path';
import automator from 'miniprogram-automator';

const OUT = path.resolve('C:/Users/cwx/OneDrive/Desktop/demo/ai-cabinet/.tmp/mp-scan-btn');
const PHONE = '13800138009';
const PASSWORD = '123456';

function log(...a) {
  console.log(new Date().toISOString(), ...a);
}

async function loginApi() {
  const res = await fetch('http://127.0.0.1/api/v2/auth/merchant-password-login', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ phoneNumber: PHONE, password: PASSWORD })
  });
  const json = await res.json();
  if (json.code !== 0 || !json.data?.token) {
    throw new Error(`login fail code=${json.code} msg=${json.message}`);
  }
  return json.data;
}

async function shot(mp, name) {
  const dest = path.join(OUT, `${name}.png`);
  await mp.screenshot({ path: dest });
  const st = fs.statSync(dest);
  log('shot', name, `${st.size}B`);
  return dest;
}

const session = await loginApi();
log('api login ok userId=', session.userId, 'tokenLen=', String(session.token).length);

const mp = await automator.connect({ wsEndpoint: 'ws://127.0.0.1:9420' });
log('automator connected');
await mp.callWxMethod('setStorageSync', 'merchant_token', session.token);
await mp.callWxMethod('setStorageSync', 'merchant_user_id', String(session.userId));
await mp.callWxMethod('setStorageSync', 'merchant_login_phone', PHONE);
await mp.callWxMethod('removeStorageSync', 'merchant_cookie_auth');
log('storage injected');

let page = await mp.reLaunch('/pages/home/home');
await new Promise((r) => setTimeout(r, 4500));
page = await mp.currentPage();
log('page', page?.path);
await shot(mp, '05-home-38009');

const scanBtn = page ? await page.$('.scan-btn') : null;
const scanCard = page ? await page.$('.scan-card') : null;
const info = { path: page?.path, phone: PHONE };
if (scanBtn) {
  info.btnText = await scanBtn.text();
  info.btnSize = await scanBtn.size();
  info.bg = await scanBtn.style('backgroundColor');
  info.color = await scanBtn.style('color');
  info.radius = await scanBtn.style('borderRadius');
  info.height = await scanBtn.style('height');
  info.fontWeight = await scanBtn.style('fontWeight');
}
if (scanCard) info.cardText = await scanCard.text();
fs.writeFileSync(path.join(OUT, 'styles-38009.json'), JSON.stringify(info, null, 2));
log('styles', JSON.stringify(info));
await shot(mp, '06-home-scan-38009');
mp.disconnect();
log('done');

