/**
 * mp-weixin 产物修补：
 * 1. app.json 补 lazyCodeLoading（uni dev 有时漏写）
 * 2. usingComponents 里指向 packages/shared-uni 的相对路径改成小程序根绝对路径
 *    （分包如 pages/messages 会把相对路径解析成「分包根下的 packages/...」→ Component is not found）
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const roots = process.argv.slice(2);
const targets =
  roots.length > 0
    ? roots
    : [join(process.cwd(), 'dist/dev/mp-weixin'), join(process.cwd(), 'dist/build/mp-weixin')];

function walkJson(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walkJson(p, out);
