    const t = await c.text();
    if (String(t).includes('已完成')) {
      await c.tap();
      break;
    }
  }
  await new Promise((r) => setTimeout(r, 1500));
  await mp.screenshot({ path: path.join(OUT, '39-replenish-card.png') });
} finally {
  mp.disconnect();
}

