input.contents:
/**
 * mp-weixin 产物修补：
 * 1. app.json 补 lazyCodeLoading
 * 2. usingComponents 相对路径改成小程序根绝对路径（分包会吃掉 ../）
 * 3. 微信把根目录 `packages/` 当成 npm 包空间，`/packages/shared-uni/...`
 *    会报 Component is not found。整树拷到 `pkg/shared-uni`（深度不变，require 仍可用）
 */
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, normalize } from 'node:path';

const roots = process.argv.slice(2);
const targets =
  roots.length > 0
    ? roots
    : [join(process.cwd(), 'dist/dev/mp-weixin'), join(process.cwd(), 'dist/build/mp-weixin')];

const SHARED_COMPONENTS = [
  'app-nav-bar',
  'app-button',
  'empty-state',
  'error-state',
  'privacy-consent-modal'
];

function walkJson(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    if (name === 'node-modules' || name === 'node_modules') continue;
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walkJson(p, out);
    else if (name.endsWith('.json')) out.push(p);
  }
  return out;
}

function remapSharedUniPath(spec) {
  return String(spec)
    .replace(/\\/g, '/')
    .replace(/(^|\/)packages\/shared-uni\//g, '$1pkg/shared-uni/')
    .replace(/^pkg\/shared-uni\//, '/pkg/shared-uni/');
}

function toAbsComponentPath(mpRoot, jsonFile, spec) {
  let s = remapSharedUniPath(spec);
  if (!s || s.startsWith('plugin://') || s.startsWith('wx://')) return s;
  if (s.startsWith('/')) return s.replace(/\.vue$/i, '');
  const resolved = normalize(join(dirname(jsonFile), s));
  const rel = relative(mpRoot, resolved).replace(/\\/g, '/');
  if (!rel || rel.startsWith('..')) return s;
  const noExt = rel.replace(/\.(vue|js)$/i, '');
  const absFile = join(mpRoot, noExt);
  if (!existsSync(`${absFile}.js`) && !existsSync(`${absFile}.json`)) return s;
  return `/${noExt}`;
}

function rewriteUsingComponents(mpRoot, jsonFile, obj) {
  const uc = obj?.usingComponents;
  if (!uc || typeof uc !== 'object') return false;
  let changed = false;
  for (const [k, v] of Object.entries(uc)) {
    if (typeof v !== 'string') continue;
    const next = toAbsComponentPath(mpRoot, jsonFile, v);
    if (next !== v) {
      uc[k] = next;
      changed = true;
    }
  }
  return changed;
}

function copySharedUniOutOfPackages(mpRoot) {
  const src = join(mpRoot, 'packages', 'shared-uni');
  const dst = join(mpRoot, 'pkg', 'shared-uni');
  if (!existsSync(src)) return false;
  mkdirSync(join(mpRoot, 'pkg'), { recursive: true });
  cpSync(src, dst, { recursive: true, force: true });
  return true;
}

let patched = 0;
for (const dir of targets) {
  const appFile = join(dir, 'app.json');
  if (!existsSync(appFile)) continue;

  copySharedUniOutOfPackages(dir);

  const app = JSON.parse(readFileSync(appFile, 'utf8'));
  let appChanged = false;
  if (app.lazyCodeLoading !== 'requiredComponents') {
    app.lazyCodeLoading = 'requiredComponents';
    appChanged = true;
  }

  const globalUc = { ...(app.usingComponents || {}) };
  for (const name of SHARED_COMPONENTS) {
    const rel = `pkg/shared-uni/src/components/${name}`;
    if (!existsSync(join(dir, `${rel}.js`))) continue;
    const abs = `/${rel}`;
    if (globalUc[name] !== abs) {
      globalUc[name] = abs;
      appChanged = true;
    }
  }
  app.usingComponents = globalUc;
  if (rewriteUsingComponents(dir, appFile, app)) appChanged = true;

  for (const file of walkJson(dir)) {
    if (file === appFile) continue;
    let json;
    try {
      json = JSON.parse(readFileSync(file, 'utf8'));
    } catch {
      continue;
    }
    if (!rewriteUsingComponents(dir, file, json)) continue;
    writeFileSync(file, `${JSON.stringify(json, null, 2)}\n`);
    patched += 1;
    console.log(`patched-uc  ${relative(dir, file)}`);
  }

  if (appChanged) {
    writeFileSync(appFile, `${JSON.stringify(app, null, 2)}\n`);
    patched += 1;
    console.log(`patched  ${appFile}`);
  } else {
    console.log(`ok  ${appFile}`);
  }
}
if (!patched && targets.every((d) => !existsSync(join(d, 'app.json')))) {
  console.warn('no app.json found under', targets.join(', '));
}

