                .map(Merchant::getMerchantName)
                .filter(name -> name != null && !name.isBlank())
                .orElse(request.getMerchantId());
    }
    return DisplayIds.merchantReplenApprovalTitle(request.getRequestId(), deviceName, merchantName);
}

