export function formatReplenRequestLine(line: {
  skuId?: string | null;
  skuName?: string | null;
  spec?: string | null;
  requestedQty?: number | null;
}): string {
  const skuId = String(line.skuId || '').trim();
  const name = String(line.skuName || '').trim();
  const spec = String(line.spec || '').trim();
  let product = name;
  if (spec && !name.includes(spec)) {
